async function syncContentfulTokens() {
  const sharedPath = path.join(ROOT, '.env.shared');
  if (!fs.existsSync(sharedPath)) return;

  const sharedMap = new Map(readEnvFile(sharedPath));
  const managementToken = sharedMap.get('CONTENTFUL_MANAGEMENT_TOKEN');
  const spaceId = sharedMap.get('CONTENTFUL_SPACE_ID');
  if (!managementToken || !spaceId) {
    console.log(
      '\n(Skipping Contentful token auto-fetch — fill in CONTENTFUL_MANAGEMENT_TOKEN and CONTENTFUL_SPACE_ID in .env.shared, then run `npm run env -- init` again.)',
    );
    return;
  }

  const { approved, login } = isTier1Approver();
  console.log(
    `\nFetching live Contentful API keys (authenticated as '${login}'${
      approved ? ', tier-1-approver' : ' — read-only, not a tier-1-approver'
    })...`,
  );

  let tokenMap;
  try {
    tokenMap = await fetchContentfulTokenMap(managementToken, spaceId);
  } catch (err) {
    console.log(`  Could not reach Contentful: ${contentfulErrorMessage(err)}`);
    return;
  }

  for (const tier of TIERS) {
    const tierPath = path.join(ROOT, `.env.${tier}`);
    if (!fs.existsSync(tierPath)) continue; // init scaffolds these first; nothing to update yet
    const contentfulEnvId = CONTENTFUL_ENV_MAP[tier];
    const tokens = tokenMap[contentfulEnvId];
    if (!tokens) {
      console.log(`  ${tier}: no Contentful API key found for environment "${contentfulEnvId}"`);
      continue;
    }
    const changes = upsertKeys(
      tierPath,
      {
        // tokenMap is keyed by real environment IDs from the API key's own
        // `environments` link — if we found a token for it, the environment
        // definitely exists, so it's safe to fill this in from the same call.
        CONTENTFUL_ENVIRONMENT_ID: contentfulEnvId,
        CONTENTFUL_DELIVERY_TOKEN: tokens.deliveryToken,
        CONTENTFUL_PREVIEW_TOKEN: tokens.previewToken,
      },
      approved,
    );
    if (!changes.length) {
      console.log(`  ${tier}: already up to date`);
    } else if (!approved) {
      console.log(`  ${tier}: ${changes.length} change(s) available — read-only, ask a tier-1-approver to run this`);
    } else {
      console.log(`  ${tier}: ${changes.map((change) => `${change.action} ${change.key}`).join(', ')}`);
    }
  }
}

